// ---------- the papers ----------

export interface BillPaper {
  kind: 'bill'
  /** The bill's row (`jobs_ledger_invoices.id`). */
  id: string
  jobId: string
  /** The job's name: "Helotes re-pipe". */
  job: string
  /** The job's number, as the bill shows it: "1312". '' when it has none. */
  number: string
  open: boolean
  /** Open: what is still open on it. Paid: the bill's amount. */
  amount: number
  billedYmd: string | null
  /** Its pay page; null for a bill not on Stripe. */
  payUrl: string | null
}

export interface EstimatePaper {
  kind: 'estimate'
  id: string
  jobId: string | null
  /** The estimate's title: "Kitchen re-pipe". */
  job: string
  number: string
  approved: boolean
  /** Its total. */
  amount: number
  sentYmd: string | null
}

export type Paper = BillPaper | EstimatePaper

const newestFirst = (a: string | null, b: string | null) => (b ?? '').localeCompare(a ?? '')

/** A person's bills: the open ones first, then the paid ones, the newest billed first in each. Owner Billing's never. */
export function billPapers(rows: { jobs: readonly PaperJobRow[]; invoices: readonly PaperInvoiceRow[]; payments: readonly PaperPaymentRow[] }): BillPaper[] {
  const jobs = new Map(rows.jobs.filter((j) => !j.billing_only).map((j) => [j.id, j]))
  const invoices = rows.invoices.filter((i) => jobs.has(i.job_id))
  const truth = computeBillTruth({ jobs: [...jobs.values()], invoices, payments: rows.payments })
  const remaining = new Map<string, number>()
  for (const r of [...truth.billed.rows, ...truth.collections.rows]) {
    if (r.invoiceId && !r.settled && !r.uncollectible) remaining.set(r.invoiceId, r.remaining)
  }
  const out: BillPaper[] = []
  for (const inv of invoices) {
    const job = jobs.get(inv.job_id)!
    if (inv.status !== 'billed' && inv.status !== 'paid') continue
    if (jobIsUncollectible(job)) continue
    const open = remaining.has(inv.id)
    out.push({
      kind: 'bill',
      id: inv.id,
      jobId: job.id,
      job: (job.job_name ?? '').trim(),
      number: effectiveJobLedgerNumber(job.hcp_number, job.click_number),
      open,
      amount: open ? remaining.get(inv.id)! : Number(inv.amount ?? 0),
      billedYmd: inv.billed_at ? calendarYmdInAppTzFromIso(inv.billed_at) || null : null,
      payUrl: (inv.stripe_invoice_id ?? '').trim() && isPayLinkId(inv.id) ? payLinkUrl(inv.id) : null,
    })
  }
  return out.sort((a, b) => Number(b.open) - Number(a.open) || newestFirst(a.billedYmd, b.billedYmd) || a.id.localeCompare(b.id))
}

/** A person's estimates once sent: the ones waiting on an answer first, then the approved ones, the newest sent first. */
export function estimatePapers(rows: readonly PaperEstimateRow[]): EstimatePaper[] {
  return rows
    .filter((e) => e.status === 'sent' || e.status === 'customer_accepted')
    .map((e) => ({
      kind: 'estimate' as const,
      id: e.id,
      jobId: e.job_ledger_id,
      job: (e.title ?? '').trim(),
      number: e.estimate_number == null ? '' : String(e.estimate_number),
      approved: e.status === 'customer_accepted',
      amount: Math.round(Number(e.total_cents ?? 0)) / 100,
      sentYmd: e.sent_at ? calendarYmdInAppTzFromIso(e.sent_at) || null : null,
    }))
    .sort((a, b) => Number(a.approved) - Number(b.approved) || newestFirst(a.sentYmd, b.sentYmd) || a.id.localeCompare(b.id))
}

/** The papers in a box: the job's own first when the box is a job's, each kind keeping its order. */
export function papersFor<T extends Paper>(papers: readonly T[], jobId: string | null): T[] {
  if (!jobId) return [...papers]
  return [...papers.filter((p) => p.jobId === jobId), ...papers.filter((p) => p.jobId !== jobId)]
}

// ---------- the fills ----------

/** What a paper puts in the blanks. `{estimate}` is made apart, for the message (`estimateLinkIo.ts`). */
export interface PaperFills {
  bill?: string | null
  amount?: string | null
  number?: string | null
  job?: string | null
}

export function paperFills(paper: Paper): PaperFills {
  if (paper.kind === 'bill') return { bill: paper.payUrl, amount: billMoney(paper.amount), number: paper.number || null, job: paper.job || null }
  return { amount: billMoney(paper.amount), number: paper.number || null, job: paper.job || null }
}

/**
 * The bill a line about money speaks of when nobody picked one. A job's box (`jobOnly`) speaks of its job's newest open
 * bill and no other; a thread speaks of the tied job's when it has one open, else the newest open bill on any job of
 * theirs. Its job's name stays the box's own. Nothing when they owe nothing.
 */
export function defaultPaperFills(papers: readonly Paper[], jobId: string | null, jobOnly = false): PaperFills {
  const open = papers.filter((p): p is BillPaper => p.kind === 'bill' && p.open)
  const onJob = jobId ? open.find((p) => p.jobId === jobId) : undefined
  const bill = jobOnly ? onJob : (onJob ?? open[0])
  if (!bill) return {}
  const fills = paperFills(bill)
  return { bill: fills.bill, amount: fills.amount, number: fills.number }
}

/**
 * The estimate a line that holds `{estimate}` speaks of when nobody picked one (v2.5645). A job's box (`jobOnly`) speaks
 * of the job's own estimate, the one still waiting on an answer first, else the approved one that made the job, and
 * never another job's, as `defaultPaperFills` holds a job's box to its own bills. A thread speaks of the tied job's,
 * else their newest sent one. Null when there is none, and the blank is left for the person.
 */
export function defaultEstimatePaper(papers: readonly Paper[], jobId: string | null, jobOnly = false): EstimatePaper | null {
  const listed = listedPapers(papers, 'estimate', jobId).filter((p): p is EstimatePaper => p.kind === 'estimate')
  const own = jobId ? listed.find((e) => e.jobId === jobId) : undefined
  return (jobOnly ? own : (own ?? listed[0])) ?? null
}

// ---------- a paper in the / list (#127 PR 2) ----------

/**
 * Whether the `/` list offers estimates: on since PR 3 (v2.5643), which makes each message's link to an estimate (a
 * second link per share, the owner's pick B, `messages/estimateLinkIo.ts`).
 */
export const ESTIMATE_LINKS_ON = true

/** How many paid bills the list shows under the open ones: a long-standing customer has dozens. */
export const PAID_BILLS_SHOWN = 3

/** The app's own words for a paper, when the team has no line for it (the to-do's table, taken as drawn). */
export const PAPER_LINES = {
  openBill: '{first}, here is your bill {number} for {job}. {amount} is open. You can pay it here: {bill}',
  paidBill: '{first}, here is a copy of your paid bill {number} for {job}: {bill}',
  estimate: '{first}, here is your estimate {number} for {job}, {amount}. Open it to choose the option you want: {estimate}',
  /** An approved estimate has been chosen already, so it goes in as a copy, as a paid bill does (v2.5645). */
  approvedEstimate: '{first}, here is a copy of your approved estimate {number} for {job}, {amount}: {estimate}',
} as const

/** The app's words for a paper: an open bill's, a paid bill's, an estimate's or an approved estimate's. */
export function paperLineWords(paper: Paper): string {
  if (paper.kind === 'estimate') return paper.approved ? PAPER_LINES.approvedEstimate : PAPER_LINES.estimate
  return paper.open ? PAPER_LINES.openBill : PAPER_LINES.paidBill
}

/** The papers the list offers for a kind: the job's first; bills open then the newest few paid; estimates while their links are on. */
export function listedPapers(papers: readonly Paper[], kind: 'bill' | 'estimate', jobId: string | null, estimatesOn = ESTIMATE_LINKS_ON): Paper[] {
  if (kind === 'estimate') return estimatesOn ? papersFor(papers.filter((p) => p.kind === 'estimate'), jobId) : []
  const bills = papersFor(
    papers.filter((p): p is BillPaper => p.kind === 'bill'),
    jobId,
  )
  const open = bills.filter((b) => b.open)
  const paid = bills.filter((b) => !b.open).slice(0, PAID_BILLS_SHOWN)
  return [...open, ...paid]
}

/** A paper's row in the list: its number, what it is for, and its money and state. */
export function paperRowWords(paper: Paper): { number: string; what: string; when: string; money: string; state: string; tone: 'open' | 'paid' | 'sent' | 'approved' } {
  const day = (ymd: string | null) => (ymd ? shortDate(ymd) : '')
  if (paper.kind === 'estimate') {
    return {
      number: paper.number ? `Estimate ${paper.number}` : 'Estimate',
      what: paper.job || 'An estimate',
      when: paper.sentYmd ? `sent ${day(paper.sentYmd)}` : 'sent',
      money: billMoney(paper.amount),
      state: paper.approved ? 'approved' : 'not approved yet',
      tone: paper.approved ? 'approved' : 'sent',
    }
  }
  return {
    number: paper.number ? `#${paper.number}` : 'A bill',
    what: paper.job || 'A bill',
    when: paper.billedYmd ? `billed ${day(paper.billedYmd)}` : 'billed',
    money: billMoney(paper.amount),
    state: paper.open ? 'open' : 'paid',
    tone: paper.open ? 'open' : 'paid',
  }
}

/** The list's title for a kind's papers: "Dana's bills". */
export function papersTitle(first: string | null, kind: 'bill' | 'estimate'): string {
  const whose = first?.trim() ? `${first.trim()}'s` : 'Their'
  return `${whose} ${kind === 'bill' ? 'bills' : 'estimates'}`
}
